// Monta o payload da mensagem interativa do tipo "flow" para a Cloud API.
const trigger = $('Quando chamado pelo Webhook').first().json;
const cfg = $('Config Disparo').first().json;

// Dados do cliente vindos do Filter & Extract do webhook do Grupo Aurora.
const msg = trigger.message || {};
const contact = trigger.contact || {};
const customerPhone = msg.from || contact.wa_id;
const customerName = (contact.profile && contact.profile.name) || '';
const phoneNumberId = trigger.phone_number_id;

if (!customerPhone) throw new Error('Sem telefone do cliente (message.from / contact.wa_id)');
if (!phoneNumberId) throw new Error('Sem phone_number_id vindo do webhook');

// flow_token: unico por sessao; o endpoint recebe ele de volta em cada request.
const flowToken = 'aurora-rest-' + customerPhone + '-' + Date.now();

const payload = {
  messaging_product: 'whatsapp',
  recipient_type: 'individual',
  to: customerPhone,
  type: 'interactive',
  interactive: {
    type: 'flow',
    header: { type: 'text', text: 'Cardápio Aurora' },
    body: { text: (customerName ? ('Olá, ' + customerName + '! ') : '') + 'Toque abaixo para montar seu pedido 🍔' },
    footer: { text: 'Grupo Aurora' },
    action: {
      name: 'flow',
      parameters: {
        flow_message_version: '3',
        flow_token: flowToken,
        flow_id: cfg.FLOW_ID,
        mode: cfg.FLOW_MODE,            // "draft" enquanto nao publicado
        flow_cta: cfg.FLOW_CTA,
        flow_action: 'data_exchange',   // abre o Flow chamando o endpoint (INIT)
      },
    },
  },
};

return [{ json: { phoneNumberId, customerPhone, flowToken, payload } }];
